        .and_then(|text| Scenario::load(&text, &stem));
    let started = Instant::now();
    let result = match loaded {
        Ok(s) if !s.applies() => {
            sum.other += 1;
            continue;
        }
        Ok(s) => {
            tokio::task::LocalSet::new()
                .run_until(super::run(&s, fixture, sum.ran + 1))
                .await
        }
        Err(e) => Err(Fail::Harness(format!("bad scenario: {e}"))),
    };
