        }
        Err(Fail::Product(e)) if ledger.pending(&item) => {
            sum.pending += 1;
            println!("pending {stem}: {e}");
        }
        Err(Fail::Product(e) | Fail::Harness(e)) => errors.push(format!("{stem}: {e}")),
    }
}
